<?php
declare(strict_types=1); namespace Joomleague\Component\Joomleague\Administrator\Table; defined('_JEXEC') or die;
use Joomla\CMS\Language\Text; use Joomla\CMS\Table\Table; use Joomla\Database\DatabaseDriver; use Joomla\Database\ParameterType; use Joomla\String\StringHelper;
final class StatisticTable extends Table { protected $_supportNullValue=true; protected $_trackAssets=false; public function __construct(DatabaseDriver $db){parent::__construct('#__joomleague_statistic','id',$db);$this->_trackAssets=false;} public function check():bool { $this->name=StringHelper::trim((string)$this->name); foreach(['code','statistic_type','scope','value_type','calculation_source'] as $field)$this->$field=strtolower(StringHelper::trim((string)$this->$field)); if((int)$this->sport_type_id<1||$this->name===''){ $this->setError(Text::_('COM_JOOMLEAGUE_ERROR_STATISTIC_REQUIRED'));return false;} foreach(['code','statistic_type','scope','value_type','calculation_source'] as $field)if(preg_match('/^[a-z][a-z0-9_]{0,99}$/',$this->$field)!==1){$this->setError(Text::_('COM_JOOMLEAGUE_ERROR_EXTENSIBLE_CODE_INVALID'));return false;} $db=$this->getDatabase();$id=(int)$this->id;$sid=(int)$this->sport_type_id;$query=$db->getQuery(true)->select('COUNT(*)')->from($db->quoteName('#__joomleague_statistic'))->where('sport_type_id=:sid')->where('code=:code')->where('id<>:id')->bind(':sid',$sid,ParameterType::INTEGER)->bind(':code',$this->code)->bind(':id',$id,ParameterType::INTEGER);if((int)$db->setQuery($query)->loadResult()>0){$this->setError(Text::_('COM_JOOMLEAGUE_ERROR_STATISTIC_CODE_DUPLICATE'));return false;}return parent::check();} }
